UPDATE /* uptReading */
       TM_CLRNDX
   SET BOOK_NUMB = #{request.bookNumb}
     , GOAL_STDT = #{request.goalStdt}
     , GOAL_ENDT = #{request.goalEndt}
     , ROND_STAT = CASE WHEN #{request.goalStdt} <= CURRENT_DATE THEN #{roundReading}
                        ELSE #{roundScheduled}
                   END
     , OPEN_DATE = CASE WHEN #{request.goalStdt} <= CURRENT_DATE
                        THEN COALESCE(OPEN_DATE, CURRENT_TIMESTAMP(6))
                        ELSE NULL
                   END
     , UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE CLUB_NUMB = #{clubNumb}
   AND ROND_NUMB = #{rondNumb}
   AND ROND_STAT IN (#{roundScheduled}, #{roundReading})

UPDATE /* uptReadingReportList */
       TM_REPORT REPORT
  JOIN TB_CLPART PART
    ON PART.REPT_NUMB = REPORT.REPT_NUMB
   SET REPORT.BOOK_NUMB = #{request.bookNumb}
     , REPORT.REPT_STDT = #{request.goalStdt}
     , REPORT.REPT_ENDT = #{request.goalEndt}
     , REPORT.UPDT_DATE = CURRENT_TIMESTAMP(6)
 WHERE PART.CLUB_NUMB = #{clubNumb}
   AND PART.ROND_NUMB = #{rondNumb}

