   SELECT /* getFindClubList */

        , MINE.MEMB_STAT
        , MINE.MEMB_ROLE
        , PENDING.JOIN_STAT
        , COALESCE(MATCHED.MATCH_CNT, 0) AS MATCH_CNT
     FROM TM_CLUBXM CLUB
LEFT JOIN TM_USERXM OWNER
       ON OWNER.USER_NUMB = CLUB.OWNR_NUMB

LEFT JOIN TB_CLMEMX MINE
       ON MINE.CLUB_NUMB = CLUB.CLUB_NUMB
      AND MINE.USER_NUMB = #{userNumb}
LEFT JOIN (  SELECT APPLICATION.CLUB_NUMB
                  , APPLICATION.USER_NUMB
                  , MAX(APPLICATION.JOIN_STAT) AS JOIN_STAT
               FROM TB_CLJOIN APPLICATION
              WHERE APPLICATION.USER_NUMB = #{userNumb}
                AND APPLICATION.JOIN_STAT = #{applicationPending}
           GROUP BY APPLICATION.CLUB_NUMB
                  , APPLICATION.USER_NUMB
          ) PENDING
       ON PENDING.CLUB_NUMB = CLUB.CLUB_NUMB
      AND PENDING.USER_NUMB = #{userNumb}
LEFT JOIN (  SELECT CATEGORY.CLUB_NUMB
                  , COUNT(*) AS MATCH_CNT
               FROM TB_CLCATE CATEGORY
               JOIN TB_USINTR INTEREST
                 ON INTEREST.INTR_CODE = CATEGORY.INTR_CODE
                AND INTEREST.USER_NUMB = #{userNumb}
           GROUP BY CATEGORY.CLUB_NUMB
          ) MATCHED
       ON MATCHED.CLUB_NUMB = CLUB.CLUB_NUMB
    WHERE CLUB.CLUB_VISB = #{clubPublic}
      AND CLUB.CLUB_STAT = #{clubActive}
      AND CLUB.OWNR_NUMB <> #{userNumb}
      AND (MINE.USER_NUMB IS NULL OR MINE.BLOC_YSNO = #{commNo})


      AND (
              CLUB.CLUB_NAME LIKE #{keywordLike}
           OR CLUB.CLUB_CNTN LIKE #{keywordLike}
          )

 ORDER BY COALESCE(MATCHED.MATCH_CNT, 0) DESC
        , CLUB.REGI_DATE DESC
        , CLUB.CLUB_NUMB DESC
    LIMIT 100

SELECT /* getClubDtl */
, MINE.MEMB_STAT , MINE.MEMB_ROLE , PENDING.JOIN_STAT , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_ROUND.ROND_NUMB END AS CURRENT_ROND_NUMB , CASE WHEN MINE.MEMB_STAT = #{memberActive} AND CURRENT_ROUND.ROND_NUMB IS NOT NULL THEN CURRENT_ROUND.ROND_NUMB WHEN MINE.MEMB_STAT = #{memberActive} THEN COALESCE(( SELECT MAX(ROUNDX.ROND_NUMB) FROM TM_CLRNDX ROUNDX WHERE ROUNDX.CLUB_NUMB = CLUB.CLUB_NUMB ), 0) + 1 END AS READING_ORDR , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_BOOK.BOOK_TITL END AS CURRENT_BOOK_TITL , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_BOOK.BOOK_NUMB END AS CURRENT_BOOK_NUMB , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_BOOK.BOOK_ATHR END AS CURRENT_BOOK_ATHR , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_BOOK.BOOK_CVIM END AS CURRENT_BOOK_CVIM , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_BOOK.BOOK_PUBL END AS CURRENT_BOOK_PUBL , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_BOOK.BOOK_ISBN END AS CURRENT_BOOK_ISBN , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_BOOK.BOOK_DESC END AS CURRENT_BOOK_DESC , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN DATE_FORMAT(CURRENT_BOOK.PUBL_DATE, '%Y-%m-%d') END AS CURRENT_PUBL_DATE , CASE WHEN MINE.MEMB_STAT = #{memberActive} AND MINE.MEMB_ROLE = #{ownerRole} THEN NOT EXISTS ( SELECT 1 FROM TB_CLPART MANAGE_PART JOIN TM_REPORT MANAGE_REPORT ON MANAGE_REPORT.REPT_NUMB = MANAGE_PART.REPT_NUMB WHERE MANAGE_PART.CLUB_NUMB = CURRENT_ROUND.CLUB_NUMB AND MANAGE_PART.ROND_NUMB = CURRENT_ROUND.ROND_NUMB AND ( MANAGE_REPORT.REPT_STAT != #{reportRead} OR TRIM(COALESCE(MANAGE_REPORT.REPT_CNTN, '')) != '' OR CAST(COALESCE(MANAGE_REPORT.REPT_GRDE, '0') AS DECIMAL(3, 1)) > 0 ) ) END AS CURRENT_BOOK_CHANGE_ALLOWED , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_ROUND.GOAL_STDT END AS CURRENT_GOAL_STDT , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_ROUND.GOAL_ENDT END AS CURRENT_GOAL_ENDT , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_REPORT.REPT_STAT END AS CURRENT_REPORT_STAT , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN CURRENT_REPORT.REPT_NUMB END AS CURRENT_REPORT_NUMB , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN COALESCE(CURRENT_GOAL.GOAL_ACHV_CNT, 0) END AS CURRENT_GOAL_ACHV_CNT , CASE WHEN MINE.MEMB_STAT = #{memberActive} THEN COALESCE(CURRENT_GOAL.GOAL_MEMB_CNT, 0) END AS CURRENT_GOAL_MEMB_CNT FROM TM_CLUBXM CLUB LEFT JOIN TM_USERXM OWNER ON OWNER.USER_NUMB = CLUB.OWNR_NUMB
LEFT JOIN TB_CLMEMX MINE ON MINE.CLUB_NUMB = CLUB.CLUB_NUMB AND MINE.USER_NUMB = #{userNumb} AND MINE.MEMB_STAT = #{memberActive} LEFT JOIN TB_CLJOIN PENDING ON PENDING.CLUB_NUMB = CLUB.CLUB_NUMB AND PENDING.USER_NUMB = #{userNumb} AND PENDING.JOIN_STAT = #{applicationPending}
LEFT JOIN TM_BKINFO CURRENT_BOOK ON CURRENT_BOOK.BOOK_NUMB = CURRENT_ROUND.BOOK_NUMB LEFT JOIN TB_CLPART CURRENT_PART ON CURRENT_PART.CLUB_NUMB = CURRENT_ROUND.CLUB_NUMB AND CURRENT_PART.ROND_NUMB = CURRENT_ROUND.ROND_NUMB AND CURRENT_PART.USER_NUMB = #{userNumb} LEFT JOIN TM_REPORT CURRENT_REPORT ON CURRENT_REPORT.REPT_NUMB = CURRENT_PART.REPT_NUMB AND CURRENT_REPORT.USER_NUMB = #{userNumb}
WHERE CLUB.CLUB_NUMB = #{clubNumb}

