SELECT /* getReadingGoalResult */ ROUNDX.CLUB_NUMB , ROUNDX.ROND_NUMB , ROUNDX.ROND_NUMB AS READING_ORDR , BOOK.BOOK_TITL , BOOK.BOOK_ATHR , BOOK.BOOK_CVIM , DATE_FORMAT(ROUNDX.GOAL_STDT, '%Y-%m-%d') AS GOAL_STDT , DATE_FORMAT(ROUNDX.GOAL_ENDT, '%Y-%m-%d') AS GOAL_ENDT , COUNT(CASE WHEN PART.ANON_YSNO = #{commNo} AND MEMBER.USER_NUMB IS NOT NULL AND USERX.USER_NUMB IS NOT NULL THEN 1 END) AS PART_CNT , COUNT(CASE WHEN PART.ANON_YSNO = #{commNo} AND MEMBER.USER_NUMB IS NOT NULL AND USERX.USER_NUMB IS NOT NULL AND PART.GOAL_YSNO = #{commYes} THEN 1 END) AS GOAL_ACHV_CNT , COUNT(CASE WHEN PART.ANON_YSNO = #{commNo} AND MEMBER.USER_NUMB IS NOT NULL AND USERX.USER_NUMB IS NOT NULL AND REPORT.REPT_STAT = #{reportDone} THEN 1 END) AS REPORT_CNT , CASE WHEN COUNT(CASE WHEN PART.USER_NUMB = #{userNumb} AND PART.ANON_YSNO = #{commNo} AND PART.GOAL_YSNO = #{commYes} THEN 1 END) > 0 THEN TRUE ELSE FALSE END AS MY_GOAL_ACHIEVED FROM ( SELECT TARGET.CLUB_NUMB , TARGET.ROND_NUMB , TARGET.BOOK_NUMB , TARGET.GOAL_STDT , TARGET.GOAL_ENDT FROM TM_CLRNDX TARGET WHERE TARGET.CLUB_NUMB = #{clubNumb} AND TARGET.ROND_STAT = #{roundCompleted}
AND TARGET.ROND_NUMB = #{rondNumb}
AND DATE(TARGET.GOAL_ENDT) = DATE_SUB(CURRENT_DATE, INTERVAL 1 DAY) ORDER BY TARGET.ROND_NUMB DESC LIMIT 1
) ROUNDX JOIN TM_BKINFO BOOK ON BOOK.BOOK_NUMB = ROUNDX.BOOK_NUMB LEFT JOIN TB_CLPART PART ON PART.CLUB_NUMB = ROUNDX.CLUB_NUMB AND PART.ROND_NUMB = ROUNDX.ROND_NUMB LEFT JOIN TB_CLMEMX MEMBER ON MEMBER.CLUB_NUMB = PART.CLUB_NUMB AND MEMBER.USER_NUMB = PART.USER_NUMB AND MEMBER.MEMB_STAT = #{memberActive} LEFT JOIN TM_USERXM USERX ON USERX.USER_NUMB = PART.USER_NUMB AND USERX.USER_STAT = #{userActive} LEFT JOIN TM_REPORT REPORT ON REPORT.REPT_NUMB = PART.REPT_NUMB AND REPORT.USER_NUMB = PART.USER_NUMB GROUP BY ROUNDX.CLUB_NUMB , ROUNDX.ROND_NUMB , ROUNDX.BOOK_NUMB , ROUNDX.GOAL_STDT , ROUNDX.GOAL_ENDT , BOOK.BOOK_TITL , BOOK.BOOK_ATHR , BOOK.BOOK_CVIM


SELECT /* getActiveMemberAccessCnt */
       COUNT(*)
  FROM TB_CLMEMX MEMBER
  JOIN TM_USERXM USERX
    ON USERX.USER_NUMB = MEMBER.USER_NUMB
   AND USERX.USER_STAT = #{userActive}
  JOIN TM_CLUBXM CLUB
    ON CLUB.CLUB_NUMB = MEMBER.CLUB_NUMB
   AND CLUB.CLUB_STAT = #{clubActive}
 WHERE MEMBER.CLUB_NUMB = #{clubNumb}
   AND MEMBER.USER_NUMB = #{userNumb}
   AND MEMBER.MEMB_STAT = #{memberActive}

SELECT /* getReadingRoundReportList */ REPORT.REPT_NUMB , REPORT.USER_NUMB , USERX.USER_NICK , FILEX.FILE_PATH AS PORF_PATH , REPORT.BOOK_NUMB , REPORT.REPT_STAT , FN_GET_CODE_NAME(#{codeReadStat}, REPORT.REPT_STAT, NULL) AS REPT_STAT_NAME , REPORT.REPT_GRDE , REPORT.REPT_CNTN , REPORT.PUBC_YSNO , COALESCE(LIKECOUNT.LIKE_CNT, 0) AS LIKE_CNT , COALESCE(USERLIKE.LIKE_YSNO, #{commNo}) AS LIKE_YSNO , COALESCE(REPLYCOUNT.REPL_CNT, 0) AS REPL_CNT , CASE WHEN FOLLOWX.USER_NUMB IS NOT NULL THEN #{commYes} ELSE #{commNo} END AS FOLLOW_YSNO FROM TB_CLPART PART JOIN TM_CLRNDX ROUNDX ON ROUNDX.CLUB_NUMB = PART.CLUB_NUMB AND ROUNDX.ROND_NUMB = PART.ROND_NUMB AND ROUNDX.ROND_STAT = #{roundCompleted} JOIN TB_CLMEMX MEMBER ON MEMBER.CLUB_NUMB = PART.CLUB_NUMB AND MEMBER.USER_NUMB = PART.USER_NUMB AND MEMBER.MEMB_STAT = #{memberActive} JOIN TM_USERXM USERX ON USERX.USER_NUMB = PART.USER_NUMB AND USERX.USER_STAT = #{userActive} JOIN TM_REPORT REPORT ON REPORT.REPT_NUMB = PART.REPT_NUMB AND REPORT.USER_NUMB = PART.USER_NUMB AND REPORT.REPT_STAT = #{reportDone} LEFT JOIN TM_FILEXM FILEX ON FILEX.FILE_NUMB = USERX.PROF_NUMB LEFT JOIN TB_FOLLOW FOLLOWX ON FOLLOWX.USER_NUMB = #{userNumb} AND FOLLOWX.FLOW_NUMB = REPORT.USER_NUMB LEFT JOIN TB_FOLLOW REVERSEX ON REVERSEX.USER_NUMB = REPORT.USER_NUMB AND REVERSEX.FLOW_NUMB = #{userNumb} LEFT JOIN ( SELECT LIKEX.TAGT_NUMB AS REPT_NUMB , COUNT(*) AS LIKE_CNT FROM TB_LIKEXX LIKEX WHERE LIKEX.TAGT_TYPE = #{likeTargetReport} GROUP BY LIKEX.TAGT_NUMB ) LIKECOUNT ON LIKECOUNT.REPT_NUMB = REPORT.REPT_NUMB LEFT JOIN ( SELECT LIKEX.TAGT_NUMB AS REPT_NUMB , #{commYes} AS LIKE_YSNO FROM TB_LIKEXX LIKEX WHERE LIKEX.USER_NUMB = #{userNumb} AND LIKEX.TAGT_TYPE = #{likeTargetReport} ) USERLIKE ON USERLIKE.REPT_NUMB = REPORT.REPT_NUMB LEFT JOIN ( SELECT REPLY.TAGT_NUMB AS REPT_NUMB , COUNT(*) AS REPL_CNT FROM TB_REPLXX REPLY WHERE REPLY.TAGT_TYPE = #{likeTargetReport} GROUP BY REPLY.TAGT_NUMB ) REPLYCOUNT ON REPLYCOUNT.REPT_NUMB = REPORT.REPT_NUMB WHERE PART.CLUB_NUMB = #{clubNumb} AND PART.ROND_NUMB = #{rondNumb} AND PART.ANON_YSNO = #{commNo}
ORDER BY CASE WHEN FOLLOWX.USER_NUMB IS NOT NULL AND REVERSEX.USER_NUMB IS NOT NULL THEN 0 WHEN FOLLOWX.USER_NUMB IS NOT NULL THEN 1 ELSE 2 END , REPORT.REPT_NUMB DESC
ORDER BY CAST(REPORT.REPT_GRDE AS DECIMAL(3, 1)) DESC , REPORT.REPT_NUMB DESC
ORDER BY COALESCE(LIKECOUNT.LIKE_CNT, 0) DESC , REPORT.REPT_NUMB DESC
ORDER BY REPORT.REPT_NUMB DESC
LIMIT #{pageOffset}, #{pageLimit}

