DELETE /* delOwnerInvitation */ MEMBER
  FROM TB_CLMEMX MEMBER
  JOIN TM_USERXM USERX
    ON USERX.USER_NUMB = MEMBER.USER_NUMB
   AND USERX.USER_STAT = #{userActive}
 WHERE MEMBER.CLUB_NUMB = #{clubNumb}
   AND MEMBER.USER_NUMB = #{userNumb}
   AND MEMBER.SEND_NUMB = #{ownerNumb}
   AND MEMBER.MEMB_STAT = #{memberInvited}
   AND MEMBER.EXPR_DATE > CURRENT_TIMESTAMP(6)

mapper.insert:


/* setJoinApplication */
INSERT INTO TB_CLJOIN (
            CLUB_NUMB
          , APPL_NUMB
          , USER_NUMB
          , QUES_FIRS
          , QUES_SECO
          , QUES_THIR
          , QUES_FOUR
          , QUES_FIFT
          , ANSR_FIRS
          , ANSR_SECO
          , ANSR_THIR
          , ANSR_FOUR
          , ANSR_FIFT
          , JOIN_STAT
          , APPL_DATE
)
SELECT #{clubNumb}
     , COALESCE(MAX(APPL_NUMB), 0) + 1
     , #{userNumb}
     , #{quesFirs}
     , #{quesSeco,jdbcType=VARCHAR}
     , #{quesThir,jdbcType=VARCHAR}
     , #{quesFour,jdbcType=VARCHAR}
     , #{quesFift,jdbcType=VARCHAR}
     , #{ansrFirs}
     , #{ansrSeco,jdbcType=VARCHAR}
     , #{ansrThir,jdbcType=VARCHAR}
     , #{ansrFour,jdbcType=VARCHAR}
     , #{ansrFift,jdbcType=VARCHAR}
     , #{applicationPending}
     , CURRENT_TIMESTAMP(6)
  FROM TB_CLJOIN
 WHERE CLUB_NUMB = #{clubNumb}

mapper.delete:

DELETE /* delOwnApplication */
  FROM TB_CLJOIN
 WHERE CLUB_NUMB = #{clubNumb}
   AND USER_NUMB = #{userNumb}
   AND JOIN_STAT = #{applicationPending}
   AND EXISTS (
       SELECT 1
         FROM TM_USERXM USERX
        WHERE USERX.USER_NUMB = #{userNumb}
          AND USERX.USER_STAT = #{userActive}
   )

mapper.update:

UPDATE /* uptJoinApplication */
       TB_CLJOIN
   SET JOIN_STAT = #{joinStat}
     , ANSR_FIRS = NULL
     , ANSR_SECO = NULL
     , ANSR_THIR = NULL
     , ANSR_FOUR = NULL
     , ANSR_FIFT = NULL
     , PROC_USER = #{ownerNumb}
     , PROC_DATE = CURRENT_TIMESTAMP(6)
 WHERE CLUB_NUMB = #{clubNumb}
   AND APPL_NUMB = #{applNumb}
   AND JOIN_STAT = #{applicationPending}
